-- Judey Phones
update public.projects set slug = 'judey-phones', name = 'Judey Phones', tagline = 'Phone hire-purchase, enforced by the phone itself', description = 'A hire-purchase platform for a phone shop in Takoradi and Accra. Customers pay a deposit, then pay weekly or monthly by Mobile Money from an app on the phone. Overdue phones lock to a payment screen and unlock the moment they pay.', overview = 'Judey Phones sells new and UK-used phones on credit. I designed and built the whole system: an Android device-owner app that lives on every financed phone, a NestJS API that schedules instalments and sends signed lock and unlock commands, a Next.js admin for staff, and the judeyphones.com storefront where customers can buy outright with Mobile Money.

The hard part is trust in both directions. The shop needs a phone it can reliably lock when payments stop; the customer needs to know a payment unlocks it immediately and that the final payment releases the phone for good. Commands are signed with Ed25519 and verified on the device, delivered over FCM, and every API call from the phone goes through certificate-pinned TLS.', category = 'product', platforms = array['Android', 'Web']::text[], role = 'Architecture, Android, backend & web', year = '2026', link = 'https://judeyphones.com', repo_url = null, image_url = '/work/judey-phones/home.webp', gallery = '[{"src":"/work/judey-phones/home.webp","alt":"judeyphones.com storefront hero","frame":"browser"},{"src":"/work/judey-phones/payment.webp","alt":"Pay in full with MoMo or pay small small","frame":"browser"},{"src":"/work/judey-phones/hire-purchase.webp","alt":"How hire purchase works","frame":"browser"},{"src":"/work/judey-phones/mobile.webp","alt":"Storefront on mobile","frame":"phone"}]'::jsonb, highlights = array['Android device-owner app in Kotlin and Jetpack Compose that locks an overdue phone to a payment screen, takes the payment in place and releases the phone after the final instalment.', 'Ed25519-signed device commands over Firebase Cloud Messaging, with root-key certificate pinning on every API call.', 'NestJS, Prisma and PostgreSQL backend with BullMQ jobs for reminders and grace periods; Paystack Mobile Money for MTN, Telecel and AT.', 'Next.js admin with permission-based staff access, and a storefront that holds stock during checkout.']::text[], tags = array['Kotlin', 'Jetpack Compose', 'NestJS', 'Prisma', 'PostgreSQL', 'Redis', 'Next.js', 'Paystack', 'Firebase', 'Docker', 'Railway']::text[], accent = '#16a34a', featured = true, is_visible = true, display_order = 1
  where slug = 'judey-phones' or (slug is null and name in ('Judey Phones'));
insert into public.projects (slug, name, tagline, description, overview, category, platforms, role, year, link, repo_url, image_url, gallery, highlights, tags, accent, featured, is_visible, display_order)
  select 'judey-phones', 'Judey Phones', 'Phone hire-purchase, enforced by the phone itself', 'A hire-purchase platform for a phone shop in Takoradi and Accra. Customers pay a deposit, then pay weekly or monthly by Mobile Money from an app on the phone. Overdue phones lock to a payment screen and unlock the moment they pay.', 'Judey Phones sells new and UK-used phones on credit. I designed and built the whole system: an Android device-owner app that lives on every financed phone, a NestJS API that schedules instalments and sends signed lock and unlock commands, a Next.js admin for staff, and the judeyphones.com storefront where customers can buy outright with Mobile Money.

The hard part is trust in both directions. The shop needs a phone it can reliably lock when payments stop; the customer needs to know a payment unlocks it immediately and that the final payment releases the phone for good. Commands are signed with Ed25519 and verified on the device, delivered over FCM, and every API call from the phone goes through certificate-pinned TLS.', 'product', array['Android', 'Web']::text[], 'Architecture, Android, backend & web', '2026', 'https://judeyphones.com', null, '/work/judey-phones/home.webp', '[{"src":"/work/judey-phones/home.webp","alt":"judeyphones.com storefront hero","frame":"browser"},{"src":"/work/judey-phones/payment.webp","alt":"Pay in full with MoMo or pay small small","frame":"browser"},{"src":"/work/judey-phones/hire-purchase.webp","alt":"How hire purchase works","frame":"browser"},{"src":"/work/judey-phones/mobile.webp","alt":"Storefront on mobile","frame":"phone"}]'::jsonb, array['Android device-owner app in Kotlin and Jetpack Compose that locks an overdue phone to a payment screen, takes the payment in place and releases the phone after the final instalment.', 'Ed25519-signed device commands over Firebase Cloud Messaging, with root-key certificate pinning on every API call.', 'NestJS, Prisma and PostgreSQL backend with BullMQ jobs for reminders and grace periods; Paystack Mobile Money for MTN, Telecel and AT.', 'Next.js admin with permission-based staff access, and a storefront that holds stock during checkout.']::text[], array['Kotlin', 'Jetpack Compose', 'NestJS', 'Prisma', 'PostgreSQL', 'Redis', 'Next.js', 'Paystack', 'Firebase', 'Docker', 'Railway']::text[], '#16a34a', true, true, 1
