-- Print Suite Pro
update public.projects set slug = 'print-suite-pro', name = 'Print Suite Pro', tagline = 'The operating system for a print shop', description = 'Desktop software for printing businesses: pricing, sales and expenses, job tracking, customers, invoices, attendance and SMS, across branches and with role-based access.', overview = 'Print Suite Pro started as a price calculator and grew into the system print shops run their day on. Owners open it in the morning to see sales, cash, debts and overdue jobs; front-desk staff use it to price work, record sales and track jobs from order to pickup.

It is a React and Electron app on Supabase. Money totals come from Postgres functions rather than client-side sums, so every screen agrees, and those functions are integration-tested against a real database. Every Home dashboard section has its own permission, checked on the server, so each person sees exactly what their role allows.', category = 'product', platforms = array['Desktop']::text[], role = 'Founder & lead engineer', year = '2025 – 2026', link = 'https://fmtsoftware.com/marketplace/print-suite-pro', repo_url = null, image_url = '/work/print-suite-pro/home-dashboard.webp', gallery = '[{"src":"/work/print-suite-pro/home-dashboard.webp","alt":"Home dashboard","frame":"desktop"},{"src":"/work/print-suite-pro/home-dashboard-dark.webp","alt":"Home dashboard in dark mode","frame":"desktop"},{"src":"/work/print-suite-pro/sales-dashboard.webp","alt":"Sales dashboard","frame":"desktop"},{"src":"/work/print-suite-pro/sales-insights.webp","alt":"Sales insights","frame":"desktop"},{"src":"/work/print-suite-pro/job-tracker.webp","alt":"Job tracker","frame":"desktop"},{"src":"/work/print-suite-pro/roles-permissions.webp","alt":"Roles and permissions","frame":"desktop"},{"src":"/work/print-suite-pro/customer-statement.webp","alt":"Customer statement","frame":"desktop"}]'::jsonb, highlights = array['Role-shaped Home dashboard where every section has its own permission, enforced server-side.', 'Job tracker with reminders delivered as native desktop notifications from the Electron main process.', 'Period totals computed in Postgres RPCs and covered by integration tests against a real Supabase project.', 'Staff attendance through a daily SMS link with server-side proximity checks, and auto-updating signed releases.']::text[], tags = array['React', 'TypeScript', 'Electron', 'Supabase', 'PostgreSQL', 'TanStack Query', 'Zustand', 'Tailwind CSS', 'Vitest']::text[], accent = '#2563eb', featured = true, is_visible = true, display_order = 2
