delete from public.work_experiences;
insert into public.work_experiences (company, role, period, location, company_url, summary, description, skills, display_order) values ('FMT Software Solutions', 'Founder & Software Engineer', 'Jan 2025 – Present', 'Accra', 'https://fmtsoftware.com', 'Faithtower Media Technologies. Business software and client websites; freelance since 2020.', array['Build and ship desktop business software with React, TypeScript, Electron and Supabase: Print Suite Pro for print shops, StockFlow for retail inventory and ChurchHub 360 for churches.', 'Built the Judey Phones hire-purchase platform: an Android device-controller app, a NestJS backend and a Next.js admin and storefront.', 'Built the FMT marketplace and its NestJS backend, with Paystack payments verified by webhook.', 'Build and maintain client websites, including iSMART and Africa Is Great, from requirements through ongoing updates.']::text[], array['React', 'TypeScript', 'Electron', 'Supabase', 'NestJS', 'Kotlin', 'Next.js', 'PostgreSQL']::text[], 1);
insert into public.work_experiences (company, role, period, location, company_url, summary, description, skills, display_order) values ('Ndel Technologies', 'Frontend Engineer · Contract', 'Jan – Feb 2026 · Apr – May 2026', 'Remote', 'https://bawahealth.com', 'BawaHealth, an AI-assisted health management platform.', array['Built patient-facing BawaHealth interfaces for profiles, medical history, appointment booking and online payment.', 'Integrated Daily.co video consultations with live transcription, screen sharing and a waiting room.', 'Added speech-to-text input and AI-based doctor recommendations to the patient flow.']::text[], array['React', 'Next.js', 'TypeScript', 'Daily.co', 'TanStack Query', 'Zustand', 'Tailwind CSS']::text[], 2);
insert into public.work_experiences (company, role, period, location, company_url, summary, description, skills, display_order) values ('KreeoAI', 'Full-Stack Engineer', 'Nov 2025 – Mar 2026', 'Remote', null, 'KreeoSync, a Figma plugin that turns design work into case studies.', array['Developed KreeoSync across its Figma plugin, web dashboard and NestJS backend on PostgreSQL (Supabase).', 'Implemented Figma OAuth and the sync that pulls design data and assets from Figma into the platform.', 'Built AI case-study generation from project notes and assets, with OpenAI speech-to-text.']::text[], array['React', 'TypeScript', 'NestJS', 'PostgreSQL', 'Supabase', 'OpenAI', 'Figma API']::text[], 3);
insert into public.work_experiences (company, role, period, location, company_url, summary, description, skills, display_order) values ('Voltbase', 'Frontend Engineer', 'Mar 2025 – Present', 'Remote', null, 'Swiftbuild, a property-management application.', array['Developed the Swiftbuild frontend from initial setup with Next.js, React and TypeScript.', 'Integrated authenticated workflows for property units and tenants, including invitations, profile updates and file uploads.', 'Extended rental and inventory interfaces with dual listings, payment integration and document signing.']::text[], array['Next.js', 'React', 'TypeScript', 'Firebase Auth', 'TanStack Query', 'Zustand', 'React Hook Form', 'Zod']::text[], 4);
insert into public.work_experiences (company, role, period, location, company_url, summary, description, skills, display_order) values ('Turntabl · Morgan Stanley', 'Software Engineer', 'Oct 2019 – Dec 2024', 'Accra', null, 'Turntabl Ghana; client assignment with Morgan Stanley from Feb 2020.', array['Built frontend features for an enterprise API marketplace and developer portal in React, TypeScript and Angular, supporting API discovery and integration.', 'Implemented self-service API deployment tooling for Azure, with API policies, semantic versioning and OpenAPI validation.', 'Developed an API usage dashboard with interactive charts and filters by client, application and response code, from Azure Application Insights.', 'Improved responsiveness through request reduction and caching; contributed to shared Angular/TypeScript libraries and parallel build pipelines.', 'Delivered React training, reviewed code and mentored frontend engineers.']::text[], array['React', 'Angular', 'TypeScript', 'Java', 'Azure', 'AWS', 'Jest', 'CI/CD']::text[], 5);

